style.css:
@-moz-document domain("chatgpt.com"), domain("chat.openai.com") {
/* ===== Fonts ===== */

*{
    font-family:
        "Iowan Old Style",
        "Baskerville",
        "Georgia",
        "Times New Roman",
        serif !important;
}

/* ===== Colors ===== */

:root{

    --bg:#0d0b10;
    --panel:#17131b;
    --panel2:#211926;

    --pink:#ff84bf;
    --pink-light:#ffb8da;

    --text:#f5edf2;
    --muted:#bca9b6;

}

/* ===== Background ===== */

html,
body,
main{
    background:var(--bg)!important;
    color:var(--text)!important;
}

/* Sidebar */

aside{
    background:#111015!important;
    border-right:1px solid #2d2230!important;
}

/* Conversation */

article{
    background:transparent!important;
}

/* User message */

[data-message-author-role="user"]{

    background:#281a25!important;
    border:1px solid #5b314a!important;

    border-radius:20px!important;
    padding:16px!important;

}

/* Assistant */

[data-message-author-role="assistant"]{

    background:#18141d!important;

    border-radius:20px!important;
    padding:16px!important;

}

/* Input */

textarea{

    background:#151219!important;
    color:var(--text)!important;

    border:1px solid #5d3550!important;

    border-radius:18px!important;

}

/* Buttons */

button{

    border-radius:14px!important;
    transition:.2s;

}

button:hover{

    background:#352133!important;

}

/* Links */

a{

    color:var(--pink)!important;

}

/* Sidebar text */

aside *{

    color:var(--pink-light)!important;

}

/* Headings */

h1,h2,h3{

    color:#ffd4e8!important;
    font-weight:600!important;
    letter-spacing:.4px;

}

  /* Top header */
header {
    background: #151219 !important;
    border-bottom: 1px solid #302233 !important;
}

/* Bottom composer area */
footer {
    background: #151219 !important;
}

/* Main app container */
#__next,
#root {
    background: #0d0b10 !important;
}

/* Everything around the conversation */
main,
section {
    background: #0d0b10 !important;
}

/* Scrollbar */

::-webkit-scrollbar{

    width:10px;

}

::-webkit-scrollbar-thumb{

    background:#5b314a;
    border-radius:100px;

}

/* Selection */

::selection{

    background:#a34776;
    color:white;

}
}
